-- =====================================================================================
-- C19-03 — Definicion PROVISIONAL del "FLUJO DE CAJA" (formato BIESS / Superintendencia que envio el area
--          financiera: cuadreSuper/02-informacion-cliente/07-Formatos/FLUJO DE CAJA_12_2025_FORMATO.xlsx) como
--          estructura de renglones de la empresa 1236, sobre el motor de C19-01.
-- Cuadre Superintendencia, tarea C19 · 2026-10-28.
--
-- ⚠ PROVISIONAL. El formato trae el mapeo contable SOLO en su columna O y solo para 9 filas (5101, 5190, 52, 53,
--   43+44, 45, 46, 47+48, 11); esas son las reglas de abajo, tal cual. Las filas de aportes, recuperacion de
--   prestamos, desembolsos, pago de cesantias/jubilaciones e inversiones no privativas son flujos de CAJA que no
--   salen de una cuenta de resultados: quedan como renglones SIN reglas (valen 0) hasta recibir el archivo con el
--   mapeo de cuentas "FLUJO DE EFECTIVO_ENE_2026 FORMATO.xlsx" (pendiente de copiar al expediente por el lider).
--   Agregar esas reglas = INSERT en CNT.CRRP, sin codigo.
-- ⚠ Observacion para el area financiera: la columna O lleva 47 (depreciaciones, amortizaciones y PROVISIONES) a
--   "Otros egresos"; no son salidas de caja. Se respeta el formato, pero hay que confirmarlo.
--
-- Diseño: base del reporte = movimiento del periodo (RPRTBSVL 2: fecha inicio .. corte, por defecto el mes).
--   Saldo inicial = saldo de 1.1 Fondos disponibles al dia anterior al inicio (renglon con base 3).
--   Totales y saldo final = formulas, igual que el Excel. Control: saldo final del flujo vs saldo contable de 1.1
--   al corte (renglones FC90/FC91, no van a ningun archivo).
-- Codigos de renglon FCnn = numero de fila del Excel del formato (FC10 = fila 10 "Saldo Inicial").
-- La "Estructura de Historia Laboral" del formato (filas 36-39: participes activos, jubilados, pago prestacional)
--   no es contable: sale de los modulos de aportes/prestaciones, no de esta estructura.
--
-- SQL PURO, SIN COMMIT. Requiere C19-01. NO SE HA EJECUTADO.
-- =====================================================================================

-- BLOQUE 1 — CONTROL ANTES. ESPERADO: 0 filas.
SELECT RPRTCDGO, RPRTNMBR, RPRTALTR, RPRTCDES FROM CNT.RPRT WHERE PJRQCDGO = 1236 AND (RPRTCDES = 'FLC' OR RPRTALTR = 7);

-- BLOQUE 2 — CABECERA (sin formato de archivo: se entrega en el Excel del BIESS)
INSERT INTO CNT.RPRT (RPRTCDGO, PJRQCDGO, RPRTNMBR, RPRTESTD, RPRTALTR, RPRTTPRP, RPRTCDES, RPRTPRDC, RPRTCDEN, RPRTBSVL, RPRTMPAU, RPRTACPF, RPRTFRAR, RPRTSMCT, RPRTTTLO)
VALUES (CNT.SQ_RPRTCDGO.NEXTVAL, 1236, 'FLUJO DE CAJA (FORMATO BIESS)', 1, 7, 2, 'FLC', 'M', '3968', 2, 0, 0, NULL, 0, 'FLUJO DE CAJA');

