-- BLOQUE 5 — CONTROL DESPUES
-- 5.1 ESPERADO: 1 cabecera, 26 renglones, 12 reglas.
SELECT r.RPRTCDGO, r.RPRTNMBR, r.RPRTALTR, (SELECT COUNT(*) FROM CNT.RNRP n WHERE n.RPRTCDGO = r.RPRTCDGO) renglones,
       (SELECT COUNT(*) FROM CNT.CRRP c WHERE c.RPRTCDGO = r.RPRTCDGO) reglas
  FROM CNT.RPRT r WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'FLC';
-- 5.2 Reglas sobre cuentas que no existen en el plan de la 1236. ESPERADO: 0 filas.
SELECT c.CRRPCNTA FROM CNT.CRRP c JOIN CNT.RPRT r ON r.RPRTCDGO = c.RPRTCDGO WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'FLC'
   AND NOT EXISTS (SELECT 1 FROM CNT.PLNN p WHERE p.PJRQCDGO = 1236 AND p.PLNNCNTA = c.CRRPCNTA);

